window.docContents[240].resolve({"/Slang/#Type-Systems--Slang___-Arithmetic-and-Boolean-Expressions--Arithmetic-and-Boolean-Expressions--Evaluation":{"contents":"Evaluating an arithmetic expression produces a number.\n\ndef Aexp.eval (a : Aexp) : Nat :=\n  match a with\n  | num   n     =>  n\n  | plus  a1 a2 =>  a1.eval + a2.eval\n  | minus a1 a2 =>  a1.eval - a2.eval\n  | mult  a1 a2 =>  a1.eval * a2.eval\ndef Aexp.eval (a : Aexp) : Nat :=\n  match a with\n  | num   n     =>  n\n  | plus  a1 a2 =>  a1.eval + a2.eval\n  | minus a1 a2 =>  a1.eval - a2.eval\n  | mult  a1 a2 =>  a1.eval * a2.eval\ndef Aexp.eval (a : Aexp) : Nat :=\n  match a with\n  | num   n     =>  n\n  | plus  a1 a2 =>  a1.eval + a2.eval\n  | minus a1 a2 =>  a1.eval - a2.eval\n  | mult  a1 a2 =>  a1.eval * a2.eval\n\n\nBy convention, we pair the definition with one simplification lemma per constructor,\nspecifying\nhow eval behaves on that constructor. Proofs then rewrite by these lemmas rather\nthan peeking through the definition of eval.  We tag each lemma @[simp], so simp\napplies them automatically.\n\n@[simp] theorem Aexp.eval_num (n : Nat) : (num n).eval = n := rfl\n@[simp] theorem Aexp.eval_plus (a1 a2 : Aexp) : (plus a1 a2).eval = a1.eval + a2.eval := rfl\n@[simp] theorem Aexp.eval_minus (a1 a2 : Aexp) : (minus a1 a2).eval = a1.eval - a2.eval := rfl\n@[simp] theorem Aexp.eval_mult (a1 a2 : Aexp) : (mult a1 a2).eval = a1.eval * a2.eval := rfl\n\nexample : Aexp.eval (.plus (.num 2) (.num 2)) = 4 := by simp\n@[simp] theorem Aexp.eval_num (n : Nat) : (num n).eval = n := rfl\n@[simp] theorem Aexp.eval_plus (a1 a2 : Aexp) : (plus a1 a2).eval = a1.eval + a2.eval := rfl\n@[simp] theorem Aexp.eval_minus (a1 a2 : Aexp) : (minus a1 a2).eval = a1.eval - a2.eval := rfl\n@[simp] theorem Aexp.eval_mult (a1 a2 : Aexp) : (mult a1 a2).eval = a1.eval * a2.eval := rfl\n\nexample : Aexp.eval (.plus (.num 2) (.num 2)) = 4 := by simp\n@[simp] theorem Aexp.eval_num (n : Nat) : (num n).eval = n := rfl\n@[simp] theorem Aexp.eval_plus (a1 a2 : Aexp) : (plus a1 a2).eval = a1.eval + a2.eval := rfl\n@[simp] theorem Aexp.eval_minus (a1 a2 : Aexp) : (minus a1 a2).eval = a1.eval - a2.eval := rfl\n@[simp] theorem Aexp.eval_mult (a1 a2 : Aexp) : (mult a1 a2).eval = a1.eval * a2.eval := rfl\n\nexample : Aexp.eval (.plus (.num 2) (.num 2)) = 4 := by simp\n\n\nSimilarly, evaluating a boolean expression yields a boolean, and we give it\nthe same treatment.\n\ndef Bexp.eval (b : Bexp) : Bool :=\n  match b with\n  | bool b     =>  b\n  | eq   a1 a2 =>  a1.eval == a2.eval\n  | neq  a1 a2 =>  a1.eval != a2.eval\n  | le   a1 a2 =>  a1.eval ≤ a2.eval\n  | gt   a1 a2 =>  a1.eval > a2.eval\n  | not  b1    =>  !eval b1\n  | and  b1 b2 =>  eval b1 && eval b2\n\n@[simp] theorem Bexp.eval_bool (b : Bool) : (bool b).eval = b := rfl\n@[simp] theorem Bexp.eval_eq (a1 a2 : Aexp) : (eq a1 a2).eval = (a1.eval == a2.eval) := rfl\n@[simp] theorem Bexp.eval_neq (a1 a2 : Aexp) : (neq a1 a2).eval = (a1.eval != a2.eval) := rfl\n@[simp] theorem Bexp.eval_le (a1 a2 : Aexp) : (le a1 a2).eval = (a1.eval ≤ a2.eval : Bool) := rfl\n@[simp] theorem Bexp.eval_gt (a1 a2 : Aexp) : (gt a1 a2).eval = (a1.eval > a2.eval : Bool) := rfl\n@[simp] theorem Bexp.eval_not (b : Bexp) : (not b).eval = !b.eval := rfl\n@[simp] theorem Bexp.eval_and (b1 b2 : Bexp) : (and b1 b2).eval = (b1.eval && b2.eval) := rfl\ndef Bexp.eval (b : Bexp) : Bool :=\n  match b with\n  | bool b     =>  b\n  | eq   a1 a2 =>  a1.eval == a2.eval\n  | neq  a1 a2 =>  a1.eval != a2.eval\n  | le   a1 a2 =>  a1.eval ≤ a2.eval\n  | gt   a1 a2 =>  a1.eval > a2.eval\n  | not  b1    =>  !eval b1\n  | and  b1 b2 =>  eval b1 && eval b2\n\n@[simp] theorem Bexp.eval_bool (b : Bool) : (bool b).eval = b := rfl\n@[simp] theorem Bexp.eval_eq (a1 a2 : Aexp) : (eq a1 a2).eval = (a1.eval == a2.eval) := rfl\n@[simp] theorem Bexp.eval_neq (a1 a2 : Aexp) : (neq a1 a2).eval = (a1.eval != a2.eval) := rfl\n@[simp] theorem Bexp.eval_le (a1 a2 : Aexp) : (le a1 a2).eval = (a1.eval ≤ a2.eval : Bool) := rfl\n@[simp] theorem Bexp.eval_gt (a1 a2 : Aexp) : (gt a1 a2).eval = (a1.eval > a2.eval : Bool) := rfl\n@[simp] theorem Bexp.eval_not (b : Bexp) : (not b).eval = !b.eval := rfl\n@[simp] theorem Bexp.eval_and (b1 b2 : Bexp) : (and b1 b2).eval = (b1.eval && b2.eval) := rfl\ndef Bexp.eval (b : Bexp) : Bool :=\n  match b with\n  | bool b     =>  b\n  | eq   a1 a2 =>  a1.eval == a2.eval\n  | neq  a1 a2 =>  a1.eval != a2.eval\n  | le   a1 a2 =>  a1.eval ≤ a2.eval\n  | gt   a1 a2 =>  a1.eval > a2.eval\n  | not  b1    =>  !eval b1\n  | and  b1 b2 =>  eval b1 && eval b2\n\n@[simp] theorem Bexp.eval_bool (b : Bool) : (bool b).eval = b := rfl\n@[simp] theorem Bexp.eval_eq (a1 a2 : Aexp) : (eq a1 a2).eval = (a1.eval == a2.eval) := rfl\n@[simp] theorem Bexp.eval_neq (a1 a2 : Aexp) : (neq a1 a2).eval = (a1.eval != a2.eval) := rfl\n@[simp] theorem Bexp.eval_le (a1 a2 : Aexp) : (le a1 a2).eval = (a1.eval ≤ a2.eval : Bool) := rfl\n@[simp] theorem Bexp.eval_gt (a1 a2 : Aexp) : (gt a1 a2).eval = (a1.eval > a2.eval : Bool) := rfl\n@[simp] theorem Bexp.eval_not (b : Bexp) : (not b).eval = !b.eval := rfl\n@[simp] theorem Bexp.eval_and (b1 b2 : Bexp) : (and b1 b2).eval = (b1.eval && b2.eval) := rfl\n\n\nIt's worth noting that ≤ and > are Prop-valued, i.e. a1.eval st ≤ a2.eval st is a proposition, but Bexp.eval returns a Bool so Lean implicitly inserts a decide coercion.\nYou can observe the call to decide by hovering over Bexp.eval_le and Bexp.eval_gt.\n\nWhat does the following expression evaluate to?Aexp.eval (.plus (.num 3) (.minus (.num 4) (.num 1)))\n(A) true    (B) false    (C) 0    (D) 3    (E) 6\n\n(E) 6\n\n","context":"Type Systems\u0009Slang: Arithmetic and Boolean Expressions\u0009Arithmetic and Boolean Expressions","header":"2.1.2. Evaluation","id":"/Slang/#Type-Systems--Slang___-Arithmetic-and-Boolean-Expressions--Arithmetic-and-Boolean-Expressions--Evaluation"},"/Types/#Type-Systems--Types___-Type-Systems--Typed-Arithmetic-Expressions--Operational-Semantics":{"contents":"Here is the single-step relation, informally.\n\n                   -----------------------------                 (ifTrue)\n                   if true then t1 else t2 ⟶ t1\n\n                   ------------------------------                (ifFalse)\n                   if false then t1 else t2 ⟶ t2\n\n                              t1 ⟶ t1'\n            -----------------------------------------------      (ifStep)\n            if t1 then t2 else t3 ⟶ if t1' then t2 else t3\n\n                              t1 ⟶ t1'\n                         -------------------                     (succStep)\n                         succ t1 ⟶ succ t1'\n\n                           -----------                           (predZero)\n                           pred 0 ⟶ 0\n\n                            IsNValue v\n                        ------------------                       (predSucc)\n                        pred (succ v) ⟶ v\n\n                              t1 ⟶ t1'\n                         -------------------                     (predStep)\n                         pred t1 ⟶ pred t1'\n\n                          ----------------                       (isZeroZero)\n                          iszero 0 ⟶ true\n\n                             IsNValue v\n                      ------------------------                   (isZeroSucc)\n                      iszero (succ v) ⟶ false\n\n                              t1 ⟶ t1'\n                       -----------------------                   (isZeroStep)\n                       iszero t1 ⟶ iszero t1'\n\n\nThe formal rules are below. We are defining them differently than we have\npreviously: We are using the relation's own notation (⟶) inside the\nconstructors. We achieve this by defining  Tm.Step within a section,\nand within that section using set_option hygiene false on ⟶ so that\nthe constructors read in this syntax; after the section\ncloses, we use a scoped notation as we have done before.\n\n\n\nsection\nset_option hygiene false in\nlocal notation:40 t:41 \" ⟶ \" t':41 => Tm.Step t t'\ninductive Tm.Step : Tm → Tm → Prop where\n  | ifTrue (t1 t2 : Tm) : <{ if true then t1 else t2 }> ⟶ t1\n  | ifFalse (t1 t2 : Tm) : <{ if false then t1 else t2 }> ⟶ t2\n  | ifStep (c c' t2 t3 : Tm) (h : c ⟶ c') :\n      <{ if c then t2 else t3 }> ⟶ <{ if c' then t2 else t3 }>\n  | succStep (t1 t1' : Tm) (h : t1 ⟶ t1') : <{ succ t1 }> ⟶ <{ succ t1' }>\n  | predZero : <{ pred 0 }> ⟶ <{ 0 }>\n  | predSucc (v : Tm) (hv : Tm.IsNValue v) : <{ pred (succ v) }> ⟶ v\n  | predStep (t1 t1' : Tm) (h : t1 ⟶ t1') : <{ pred t1 }> ⟶ <{ pred t1' }>\n  | isZeroZero : <{ iszero 0 }> ⟶ <{ true }>\n  | isZeroSucc (v : Tm) (hv : Tm.IsNValue v) : <{ iszero (succ v) }> ⟶ <{ false }>\n  | isZeroStep (t1 t1' : Tm) (h : t1 ⟶ t1') : <{ iszero t1 }> ⟶ <{ iszero t1' }>\nend\n\nscoped notation:40 t:41 \" ⟶ \" t':41 => Tm.Step t t'\nsection\nset_option hygiene false in\nlocal notation:40 t:41 \" ⟶ \" t':41 => Tm.Step t t'\ninductive Tm.Step : Tm → Tm → Prop where\n  | ifTrue (t1 t2 : Tm) : <{ if true then t1 else t2 }> ⟶ t1\n  | ifFalse (t1 t2 : Tm) : <{ if false then t1 else t2 }> ⟶ t2\n  | ifStep (c c' t2 t3 : Tm) (h : c ⟶ c') :\n      <{ if c then t2 else t3 }> ⟶ <{ if c' then t2 else t3 }>\n  | succStep (t1 t1' : Tm) (h : t1 ⟶ t1') : <{ succ t1 }> ⟶ <{ succ t1' }>\n  | predZero : <{ pred 0 }> ⟶ <{ 0 }>\n  | predSucc (v : Tm) (hv : Tm.IsNValue v) : <{ pred (succ v) }> ⟶ v\n  | predStep (t1 t1' : Tm) (h : t1 ⟶ t1') : <{ pred t1 }> ⟶ <{ pred t1' }>\n  | isZeroZero : <{ iszero 0 }> ⟶ <{ true }>\n  | isZeroSucc (v : Tm) (hv : Tm.IsNValue v) : <{ iszero (succ v) }> ⟶ <{ false }>\n  | isZeroStep (t1 t1' : Tm) (h : t1 ⟶ t1') : <{ iszero t1 }> ⟶ <{ iszero t1' }>\nend\n\nscoped notation:40 t:41 \" ⟶ \" t':41 => Tm.Step t t'\nsection\nset_option hygiene false in\nlocal notation:40 t:41 \" ⟶ \" t':41 => Tm.Step t t'\ninductive Tm.Step : Tm → Tm → Prop where\n  | ifTrue (t1 t2 : Tm) : <{ if true then t1 else t2 }> ⟶ t1\n  | ifFalse (t1 t2 : Tm) : <{ if false then t1 else t2 }> ⟶ t2\n  | ifStep (c c' t2 t3 : Tm) (h : c ⟶ c') :\n      <{ if c then t2 else t3 }> ⟶ <{ if c' then t2 else t3 }>\n  | succStep (t1 t1' : Tm) (h : t1 ⟶ t1') : <{ succ t1 }> ⟶ <{ succ t1' }>\n  | predZero : <{ pred 0 }> ⟶ <{ 0 }>\n  | predSucc (v : Tm) (hv : Tm.IsNValue v) : <{ pred (succ v) }> ⟶ v\n  | predStep (t1 t1' : Tm) (h : t1 ⟶ t1') : <{ pred t1 }> ⟶ <{ pred t1' }>\n  | isZeroZero : <{ iszero 0 }> ⟶ <{ true }>\n  | isZeroSucc (v : Tm) (hv : Tm.IsNValue v) : <{ iszero (succ v) }> ⟶ <{ false }>\n  | isZeroStep (t1 t1' : Tm) (h : t1 ⟶ t1') : <{ iszero t1 }> ⟶ <{ iszero t1' }>\nend\n\nscoped notation:40 t:41 \" ⟶ \" t':41 => Tm.Step t t'\n\n\nThe Tm.IsNValue premises in predSucc and isZeroSucc are needed\nfor determinism (this will be proved in an optional exercise below).\n\nNotice that the Tm.Step relation doesn't care about whether the\nexpression being stepped makes global sense — it just checks that the\noperation in the next reduction step is being applied to the right\nkinds of operands.  For example, the term succ true cannot take a\nstep, but the almost as obviously nonsensical termsucc (if true then true else true)\ncan take a step (once, before becoming stuck).\n\n","context":"Type Systems\u0009Types: Type Systems\u0009Typed Arithmetic Expressions","header":"4.1.2. Operational Semantics","id":"/Types/#Type-Systems--Types___-Type-Systems--Typed-Arithmetic-Expressions--Operational-Semantics"}});